module max_excursion (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] valid,\n    input [31:0] arr_0,\n    input [31:0] arr_1,\n    input [31:0] arr_2,\n    input [31:0] arr_3,\n    input [31:0] arr_4,\n    input [31:0] arr_5,\n    input [31:0] arr_6,\n    input [31:0] arr_7,\n    output reg [7:0] max_size,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] S_IDLE         = 4'd0;\n    localparam [3:0] S_DECODE       = 4'd1;\n    localparam [3:0] S_ENUM_START   = 4'd2;\n    localparam [3:0] S_ENUM_CHECK   = 4'd3;\n    localparam [3:0] S_ENUM_POPCOUNT = 4'd4;\n\n    reg [3:0] state;\n    reg [7:0] mask_reg;\n    reg [7:0] max_size_reg;\n    reg [2:0] i_idx, j_idx;\n    reg checking_valid;\n\n    // Registered attributes\n    reg [11:0] height_0, height_1, height_2, height_3, height_4, height_5, height_6, height_7;\n    reg sex_0, sex_1, sex_2, sex_3, sex_4, sex_5, sex_6, sex_7;\n    reg [7:0] music_0, music_1, music_2, music_3, music_4, music_5, music_6, music_7;\n    reg [7:0] sport_0, sport_1, sport_2, sport_3, sport_4, sport_5, sport_6, sport_7;\n\n    // Compatibility signals\n    reg [11:0] h_i, h_j;\n    reg sex_i, sex_j;\n    reg [7:0] music_i, music_j, sport_i, sport_j;\n    wire comp_ij;\n\n    // Popcount\n    wire [7:0] popcount_result = mask_reg[0] + mask_reg[1] + mask_reg[2] + mask_reg[3] + mask_reg[4] + mask_reg[5] + mask_reg[6] + mask_reg[7];\n\n    // Compatibility computation\n    assign comp_ij = (h_i > (h_j + 12'd40)) || (h_j > (h_i + 12'd40)) ||\n                    (sex_i == sex_j) || (music_i != music_j) || (sport_i == sport_j);\n\n    // FSM\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            max_size <= 8'd0;\n            mask_reg <= 8'd0;\n            max_size_reg <= 8'd0;\n            checking_valid <= 1'b0;\n            i_idx <= 3'd0;\n            j_idx <= 3'd0;\n            height_0 <= 12'd0; height_1 <= 12'd0; height_2 <= 12'd0; height_3 <= 12'd0;\n            height_4 <= 12'd0; height_5 <= 12'd0; height_6 <= 12'd0; height_7 <= 12'd0;\n            sex_0 <= 1'b0; sex_1 <= 1'b0; sex_2 <= 1'b0; sex_3 <= 1'b0;\n            sex_4 <= 1'b0; sex_5 <= 1'b0; sex_6 <= 1'b0; sex_7 <= 1'b0;\n            music_0 <= 8'd0; music_1 <= 8'd0; music_2 <= 8'd0; music_3 <= 8'd0;\n            music_4 <= 8'd0; music_5 <= 8'd0; music_6 <= 8'd0; music_7 <= 8'd0;\n            sport_0 <= 8'd0; sport_1 <= 8'd0; sport_2 <= 8'd0; sport_3 <= 8'd0;\n            sport_4 <= 8'd0; sport_5 <= 8'd0; sport_6 <= 8'd0; sport_7 <= 8'd0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) state <= S_DECODE;\n                end\n\n                S_DECODE: begin\n                    height_0 <= arr_0[15:4];  sport_0 <= arr_0[31:24];  music_0 <= arr_0[23:16];  sex_0 <= arr_0[3];\n                    height_1 <= arr_1[15:4];  sport_1 <= arr_1[31:24];  music_1 <= arr_1[23:16];  sex_1 <= arr_1[3];\n                    height_2 <= arr_2[15:4];  sport_2 <= arr_2[31:24];  music_2 <= arr_2[23:16];  sex_2 <= arr_2[3];\n                    height_3 <= arr_3[15:4];  sport_3 <= arr_3[31:24];  music_3 <= arr_3[23:16];  sex_3 <= arr_3[3];\n                    height_4 <= arr_4[15:4];  sport_4 <= arr_4[31:24];  music_4 <= arr_4[23:16];  sex_4 <= arr_4[3];\n                    height_5 <= arr_5[15:4];  sport_5 <= arr_5[31:24];  music_5 <= arr_5[23:16];  sex_5 <= arr_5[3];\n                    height_6 <= arr_6[15:4];  sport_6 <= arr_6[31:24];  music_6 <= arr_6[23:16];  sex_6 <= arr_6[3];\n                    height_7 <= arr_7[15:4];  sport_7 <= arr_7[31:24];  music_7 <= arr_7[23:16];  sex_7 <= arr_7[3];\n                    mask_reg <= 8'd1;\n                    state <= S_ENUM_START;\n                end\n\n                S_ENUM_START: begin\n                    if (mask_reg == 8'd0) begin\n                        max_size <= max_size_reg;\n                        done <= 1'b1;\n                        state <= S_IDLE;\n                    end else begin\n                        if ((mask_reg & ~valid) == 8'd0) begin\n                            checking_valid <= 1'b1;\n                            i_idx <= 3'd0;\n                            j_idx <= 3'd1;\n                            state <= S_ENUM_CHECK;\n                        end else begin\n                            mask_reg <= {1'b0, mask_reg[7:1]};\n                        end\n                    end\n                end\n\n                S_ENUM_CHECK: begin\n                    if (i_idx < 3'd7 && j_idx <= 3'd7) begin\n                        if (mask_reg[i_idx] && mask_reg[j_idx]) begin\n                            h_i <= (i_idx == 3'd0) ? height_0 :\n                                   (i_idx == 3'd1) ? height_1 :\n                                   (i_idx == 3'd2) ? height_2 :\n                                   (i_idx == 3'd3) ? height_3 :\n                                   (i_idx == 3'd4) ? height_4 :\n                                   (i_idx == 3'd5) ? height_5 :\n                                   (i_idx == 3'd6) ? height_6 : height_7;\n                            h_j <= (j_idx == 3'd0) ? height_0 :\n                                   (j_idx == 3'd1) ? height_1 :\n                                   (j_idx == 3'd2) ? height_2 :\n                                   (j_idx == 3'd3) ? height_3 :\n                                   (j_idx == 3'd4) ? height_4 :\n                                   (j_idx == 3'd5) ? height_5 :\n                                   (j_idx == 3'd6) ? height_6 : height_7;\n                            sex_i <= (i_idx == 3'd0) ? sex_0 :\n                                    (i_idx == 3'd1) ? sex_1 :\n                                    (i_idx == 3'd2) ? sex_2 :\n                                    (i_idx == 3'd3) ? sex_3 :\n                                    (i_idx == 3'd4) ? sex_4 :\n                                    (i_idx == 3'd5) ? sex_5 :\n                                    (i_idx == 3'd6) ? sex_6 : sex_7;\n                            sex_j <= (j_idx == 3'd0) ? sex_0 :\n                                    (j_idx == 3'd1) ? sex_1 :\n                                    (j_idx == 3'd2) ? sex_2 :\n                                    (j_idx == 3'd3) ? sex_3 :\n                                    (j_idx == 3'd4) ? sex_4 :\n                                    (j_idx == 3'd5) ? sex_5 :\n                                    (j_idx == 3'd6) ? sex_6 : sex_7;\n                            music_i <= (i_idx == 3'd0) ? music_0 :\n                                      (i_idx == 3'd1) ? music_1 :\n                                      (i_idx == 3'd2) ? music_2 :\n                                      (i_idx == 3'd3) ? music_3 :\n                                      (i_idx == 3'd4) ? music_4 :\n                                      (i_idx == 3'd5) ? music_5 :\n                                      (i_idx == 3'd6) ? music_6 : music_7;\n                            music_j <= (j_idx == 3'd0) ? music_0 :\n                                      (j_idx == 3'd1) ? music_1 :\n                                      (j_idx == 3'd2) ? music_2 :\n                                      (j_idx == 3'd3) ? music_3 :\n                                      (j_idx == 3'd4) ? music_4 :\n                                      (j_idx == 3'd5) ? music_5 :\n                                      (j_idx == 3'd6) ? music_6 : music_7;\n                            sport_i <= (i_idx == 3'd0) ? sport_0 :\n                                      (i_idx == 3'd1) ? sport_1 :\n                                      (i_idx == 3'd2) ? sport_2 :\n                                      (i_idx == 3'd3) ? sport_3 :\n                                      (i_idx == 3'd4) ? sport_4 :\n                                      (i_idx == 3'd5) ? sport_5 :\n                                      (i_idx == 3'd6) ? sport_6 : sport_7;\n                            sport_j <= (j_idx == 3'd0) ? sport_0 :\n                                      (j_idx == 3'd1) ? sport_1 :\n                                      (j_idx == 3'd2) ? sport_2 :\n                                      (j_idx == 3'd3) ? sport_3 :\n                                      (j_idx == 3'd4) ? sport_4 :\n                                      (j_idx == 3'd5) ? sport_5 :\n                                      (j_idx == 3'd6) ? sport_6 : sport_7;\n                            if (comp_ij) checking_valid <= 1'b0;\n                        end\n                        if (j_idx == 3'd7) begin\n                            i_idx <= i_idx + 3'd1;\n                            j_idx <= i_idx + 3'd2;\n                        end else begin\n                            j_idx <= j_idx + 3'd1;\n                        end\n                    end else begin\n                        if (checking_valid) state <= S_ENUM_POPCOUNT;\n                        else begin\n                            mask_reg <= {1'b0, mask_reg[7:1]};\n                            state <= S_ENUM_START;\n                        end\n                    end\n                end\n\n                S_ENUM_POPCOUNT: begin\n                    if (popcount_result > max_size_reg) max_size_reg <= popcount_result;\n                    mask_reg <= {1'b0, mask_reg[7:1]};\n                    state <= S_ENUM_START;\n                end\n\n                default: state <= S_IDLE;\n            endcase\n        end\n    end\nendmodule